import{_ as l,h as o,i as a,c as s,v as t,p as n,x as r,m,e as h,S as p}from"./chunks/framework.Dvtg8yj2.js";const u=JSON.parse('{"title":"群体相对基线","description":"","frontmatter":{"title":"群体相对基线","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/group-relative-baseline.md","filePath":"llm/group-relative-baseline.md","lastUpdated":1788454257000}'),d={name:"llm/group-relative-baseline.md"};function E(c,e,A,_,f,B){const i=o("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="群体相对基线" tabindex="-1">群体相对基线 <a class="header-anchor" href="#群体相对基线" aria-label="Permalink to &quot;群体相对基线&quot;">​</a></h1><div class="epigraph"><p>对每个提示采样一组输出，用组内奖励的均值与标准差来估计优势，从而不必训练与策略同规模的价值模型。</p><footer>—— Shao et al., DeepSeekMath: Pushing the Limits of Mathematical Reasoning in Open Language Models, 2024</footer></div><p><a href="/llm/critic-free-advantage">不依赖 Critic 的优势</a>有许多 \\(g\\)。群体相对基线是其中被 DeepSeekMath 写成公式、又被 <a href="/llm/deepseek-r1">DeepSeek-R1</a> 大规模用起来的那一个：同一提示采 \\(G\\) 条，减均值、除标准差，得到只在 <em>这一组里</em> 可比的 \\(\\hat{A}_i\\)。它不估计绝对「这道题有多难」，只估计「这 \\(G\\) 条谁更好」。本篇把这条基线当成一种对照实验设计，而不是当成与 PPO 并列的全新优化理论。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>不同提示的原始回报不可比。一道小学算术的 \\(R=1\\) 和一道竞赛题的 \\(R=1\\) 含义不同；奖励模型对长答案的尺度漂移，会让绝对 \\(R\\) 大的提示抢走步长。若用全局滑动均值当 \\(b\\)，简单题的 \\(1-\\bar{r}\\) 长期为正，难题的 \\(0-\\bar{r}\\) 长期为负，策略被推向「把简单题再写一遍」。需要一种基线，其尺度 <em>跟着当前提示、当前策略的局部样本走</em>。</p><p>群体相对把对照范围收成一个提示。只要 \\(G\\ge 2\\) 且组内有变异，优势自动变成零均值（在减均值的定义下），难题与易题的学习率不再被绝对正确率绑架。代价立刻出现：必须为每个提示付 \\(G\\) 倍的生成；组内无变异时梯度为零；用组内标准差再去除时，小 \\(G\\) 的尺度估计本身很噪。</p><h3 id="时相对性消失" tabindex="-1">\\(G=1\\) 时相对性消失 <a class="header-anchor" href="#时相对性消失" aria-label="Permalink to &quot;$G=1$ 时相对性消失&quot;">​</a></h3><p>\\(G=1\\) 没有组内同伴，均值就是自己，减均值后优势恒为 0，训练空转。有人把 \\(G=1\\) 配一个全局标准差，那已经不是群体相对，而是批次标准化的 <a href="/llm/reinforce-llm">REINFORCE</a>。复现 R1-Zero 却把组大小改成 1，长度与反思都不必出现——不是随机种子差，是基线定义被改掉了。</p><p><span class="marginnote">组是 <em>同一提示</em> 的独立样本，不是一个 batch 里碰巧相邻的不同题。跨提示拼成「假组」会把难度差写进优势：难题的错答可能相对简单题的对答为负，梯度在惩罚难度而不是惩罚错误解法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对提示 \\(x\\) 采样 \\(\\{y_i\\}_{i=1}^{G}\\)，回报 \\(r_i=R(x,y_i)\\)。DeepSeekMath 采用的组相对优势为</p> \\[\\hat{A}_i = \\frac{r_i - \\mathrm{mean}(\\mathbf{r})} {\\mathrm{std}(\\mathbf{r})+\\varepsilon}. \\]<p>\\(\\mathrm{mean}\\) 与 \\(\\mathrm{std}\\) 都只在这 \\(G\\) 个数上算。\\(\\varepsilon\\) 防止全相等时除零。随后 \\(\\hat{A}_i\\) 广播到 \\(y_i\\) 的每个 token，再进入带 KL 或裁剪的策略梯度。组内标准化使 \\(\\hat{A}\\) 的典型幅度约为 1，学习率可以在不同奖励量纲（0/1 与偏好分）之间少调一档。</p><h3 id="全对、全错与「假方差」" tabindex="-1">全对、全错与「假方差」 <a class="header-anchor" href="#全对、全错与「假方差」" aria-label="Permalink to &quot;全对、全错与「假方差」&quot;">​</a></h3><p>若 \\(G\\) 条全是 1 或全是 0，\\(\\mathrm{std}=0\\)，优势定义为 0，该提示本步不更新。这是在说：当前策略在这道题上没有 <em>可对比的</em> 成功或失败，Monte Carlo 给不出方向。加大 \\(G\\)、提高温度、或换更难/更易的题，才能重新制造变异。不要在 \\(\\mathrm{std}\\) 过小时用一个任意的全局常数去「补梯度」——那会把绝对尺度从后门放回来，且对全对组与全错组给予同号或同幅度的错误信号。</p><p>若 \\(G\\) 很小（例如 2）且两条回报只差在格式分的小数上，\\(\\mathrm{std}\\) 会把微小差放大成 \\(\\pm 1\\) 量级。此时模型会过度拟合格式，而不是解法。缓解是：奖励设计避免无意义的微差、或对 \\(\\mathrm{std}\\) 设下限、或改用全局标准差只做尺度、组均值仍做对照。后一种已经离开 DeepSeekMath 的原文公式，写配置时必须标明。</p>',16)),(a(),n(p,null,{default:r(()=>[h(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%8F%90%E7%A4%BA%20x%22%5D%20--%3E%20G1%5B%22%E9%87%87%E6%A0%B7%20G%20%E6%9D%A1%E5%9B%9E%E5%A4%8D%22%5D%0A%20%20G1%20--%3E%20R%5B%22r1%20%E2%80%A6%20rG%22%5D%0A%20%20R%20--%3E%20M%5B%22%E7%BB%84%E5%9D%87%E5%80%BC%22%5D%0A%20%20R%20--%3E%20S%5B%22%E7%BB%84%E6%A0%87%E5%87%86%E5%B7%AE%22%5D%0A%20%20R%20--%3E%20A%5B%22A%CC%82i%20%3D%20(ri%20%E2%88%92%20mean)%20%2F%20std%22%5D%0A%20%20M%20--%3E%20A%0A%20%20S%20--%3E%20A%0A%20%20A%20--%3E%20Z%7B%22%E7%BB%84%E5%86%85%E6%9C%89%E5%8F%98%E5%BC%82%3F%22%7D%0A%20%20Z%20--%3E%7C%E5%90%A6%7C%20ZERO%5B%22A%CC%82%20%3D%200%EF%BC%8C%E6%9C%AC%E6%8F%90%E7%A4%BA%E4%B8%8D%E6%9B%B4%E6%96%B0%22%5D%0A%20%20Z%20--%3E%7C%E6%98%AF%7C%20PG%5B%22%E5%90%84%E6%9D%A1%E4%B9%98%20%E2%88%87%20log%20%CF%80%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[m(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>减均值相当于在当前提示的经验分布上把 \\(V(x)\\) 换成样本均值。这正是 Williams 基线在「用同状态的其他动作估计 \\(b\\)」时的有限样本版。除标准差则是额外的仿射：它不改变组内排序，改变的是 <em>步长对组内离散程度的灵敏度</em>。离散大（有对有错）时除数大，更新温和；离散小（只差一点点）时除数小，更新被放大——与「信号清晰时应更大步」的直觉相反。这是群体相对最容易被忽略的机制，也是小 \\(G\\) 上格式崩的来源。</p><p>因为 \\(\\hat{A}_i\\) 对整段广播，组内「更好」的那条，其错误前缀也会被加强。相对的是 <em>终局</em>，不是逐步正确性。R1-Zero 用规则奖励只看最终答案，群体相对会强化「碰巧答对」的长链，包括看起来像推理、中间步骤错误的轨迹。要压这种假推理，需要过程监督或逐步核对，而不是把 \\(G\\) 再加大。</p><p><span class="marginnote">温度与 \\(G\\) 耦合。温度过低，组内重复，标准差塌缩；温度过高，组内都是胡话，相对排名变成噪声比赛。应在目标任务上扫 \\((G,T)\\)，不要从博客抄一组未注明数据配比的数。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><h3 id="相对性解决尺度-不解决奖励错了" tabindex="-1">相对性解决尺度，不解决奖励错了 <a class="header-anchor" href="#相对性解决尺度-不解决奖励错了" aria-label="Permalink to &quot;相对性解决尺度，不解决奖励错了&quot;">​</a></h3><p>群体相对不能修正系统性错误的 \\(R\\)。若奖励模型偏爱谄媚，组内最谄媚的样本优势最高，策略仍会谄媚。若规则只解析 <code>\\boxed{}</code> 而解析器脆弱，组内「格式更像」的样本获胜。评测必须用与训练解析器独立的核对，否则相对基线会把解析漏洞放大成主梯度。</p><p>\\(G\\) 增大降低优势噪声，但线性增加 decode 成本，并提高「全对」概率（策略变强后）。训练后期有效梯度变稀，需要题库变难、或对零优势提示做过采样，而不是无限加大 \\(G\\)。与 <a href="/llm/best-of-n">Best-of-N</a> 的差别：Best-of-N 在 <em>推理</em> 时用相对排序选出一条；群体相对在 <em>训练</em> 时用相对优势更新参数。两者都消耗同题多样本，不要把推理 BoN 的 \\(N\\) 和训练 \\(G\\) 写成同一个超参而不说明阶段。</p><p><span class="marginnote">GRPO 原文在 DeepSeekMath（2024），R1（2025）是大规模采用而不是第一次发明。写出处时不要把组相对基线记成 2025 年才出现。公式以报告为准，第三方框架对 std 的无偏估计（除 \\(G\\) 还是 \\(G-1\\)）、对 \\(\\varepsilon\\) 的默认值都会改数值，对不齐就不要比「谁复现失败」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>群体相对基线在同一提示的 \\(G\\) 条回报上减均值、通常再除标准差，得到提示内可比的优势。</li><li>它消除的是跨题尺度差异，不提供逐步信用，也不纠正错误的奖励定义。</li><li>\\(G=1\\) 或组内零方差时优势为 0；这是没有对照，应改 \\(G\\)、温度或题难，而不是暗塞全局常数。</li><li>除组内 std 会把微差放大，小 \\(G\\) 上需警惕格式过拟合。</li><li>训练后期全对增多会使有效更新变稀，要动数据难度而不只动 \\(G\\)。</li><li>推理 Best-of-N 与训练组大小 \\(G\\) 同构于「同题多样本」，但一个改输出、一个改参数。</li><li>出处：Shao et al., <em>DeepSeekMath</em>, 2024；DeepSeek-AI, <em>DeepSeek-R1</em>, 2025。</li></ul>',11))])}const b=l(d,[["render",E]]);export{u as __pageData,b as default};
